import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy technical acceptance checklist","description":"Updated October 26, 2026. Christian owns technical acceptance. Follow the technical design addendum, database reference, flow, device checks and V2 requirements.","frontmatter":{"title":"Chainy technical acceptance checklist","description":"Updated October 26, 2026. Christian owns technical acceptance. Follow the technical design addendum, database reference, flow, device checks and V2 requirements.","source":"docs/requirements/technical-requirements.md","category":"Requirements","sourceUpdated":"2026-10-26T18:51:49+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/technical-requirements.md","filePath":"content/docs/requirements/technical-requirements.md"}'),r={name:"content/docs/requirements/technical-requirements.md"};function c(o,e,s,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-technical-acceptance-checklist">Chainy technical acceptance checklist<a class="header-anchor" href="#chainy-technical-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Updated October 26, 2026. Christian owns technical acceptance. Follow the <a href="/Chainy-Docs/content/docs/technical-design.html">technical design addendum</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a>, <a href="/Chainy-Docs/content/docs/design/app-flow.html">flow</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">device checks</a> and <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">V2 requirements</a>.</p><p>Before <strong>November 10 Cryptita Plays community beta testing</strong>:</p><ul><li>Record actual source revision, Unity version, Android settings, SQLite binding and tested device. Configure Android 10 / API level 29 as the minimum OS. The required minimum reference phone has 4 GB RAM, 128 GB total storage and a reported 2.3 GHz octa-core CPU; do not record IMEI, MAC address or other device identifiers.</li><li>Reuse project architecture; UI presents, handlers call services, typed events notify, and Database Manager owns SQL/transactions.</li><li>Allow one active interaction; disable world input during dialogue, loading or pending operation.</li><li>Verify W01–W04 and B01–B03/demo B07 with approved examples and shared record identity.</li><li>Commit balance, inventory, ledger, quest/reward and restoration together; test duplicate taps, repeat save, interruption and failure.</li><li>Persist profile, version, quest, journal/encyclopedia and checkpoint state. Demonstrate profile separation and reliable reload without silent reset.</li><li>Test pause/back, recoverable loading/save errors and signed update preservation using synthetic records.</li><li>Measure readability, device behavior and performance on the minimum reference phone; testing only on a higher-spec phone or in the editor is not Android acceptance.</li><li>Label local demo profiles honestly. Teacher provisioning/pairing/collection is later scope; no simulated security presented as implemented.</li><li>If AI stretch is admitted, prove actual local training and separation of training, practice and reserved final cases.</li></ul><p>Standalone Wordle and BlockMatch are full-product work, not beta prerequisites. No game code, schema or migration is changed by this documentation update. <strong>Pre-final remains November 21, 2026.</strong></p></div>',1)])])}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
